    26	// Map ENDTOEND event format to RawEventInput
    27	function mapToRawEventInput(event: any, source: string): RawEventInput {
    28	  // Kulturhuset scraper provides start_time (full ISO timestamp) and time (HH:MM)
    29	  // Other scrapers may only provide time. Prefer full timestamp when available.
    30	  const fullTimestamp = event.start_time || `${event.date}T${event.time}`;
    31	  
    32	  return {
    33	    source,
    34	    source_id: event.id,
    35	    title: event.title,
    36	    description: event.description || '',
    37	    start_date: event.date,
    38	    start_time: fullTimestamp,  // Use full timestamp (ISO 8601), not just time
    39	    end_date: event.date,
    40	    end_time: event.time,
    41	    venue_name: event.venue,
    42	    venue_city: event.area || 'Stockholm',
    43	    venue_address: event.address || '',
    44	    venue_lat: event.lat || null,
    45	    venue_lng: event.lng || null,
    46	    category: event.category || 'culture',
    47	    url: event.url || '',
    48	    image_url: event.image_url || event.imageUrl || null,
    49	    price_info: event.price_info || event.priceInfo || null,
    50	    promoter: event.promoter || null,
    51	    organizer: event.organizer || null,
    52	    accessibility: event.accessibility || null,
    53	    age_restriction: event.age_restriction || event.ageRestriction || null,
    54	    tags: event.tags || [],
    55	    raw_data: event,
    56	  };
    57	}
