    59	// Queue events from any source
    60	async function queueEvents(events: any[], source: string): Promise<number> {
    61	  let queued = 0;
    62	  for (const event of events) {
    63	    try {
    64	      const rawEvent = mapToRawEventInput(event, source);
    65	      // BullMQ job IDs cannot contain ':' - replace with '-'
    66	      const safeJobId = `${source}-${event.id}`.replace(/:/g, '-');
    67	      await rawEventsQueue.add('process-raw-event', rawEvent, {
    68	        jobId: safeJobId,
    69	      });
    70	      queued++;
    71	    } catch (err) {
    72	      console.error(`[${source}] Failed to queue event ${event.id}:`, err);
    73	    }
    74	  }
    75	  return queued;
    76	}
