    78	// Run a single source
    79	export async function runSource(
    80	  name: string,
    81	  fetchFn: () => Promise<any[]>,
    82	  options?: { filterFn?: (e: any) => boolean }
    83	): Promise<SourceResult> {
    84	  console.log(`[sources] Running source: ${name}`);
    85	  const result: SourceResult = {
    86	    source: name,
    87	    eventsQueued: 0,
    88	    eventsFound: 0,
    89	    errors: [],
    90	    status: 'success',
    91	  };
    92	
    93	  try {
    94	    const events = await fetchFn();
    95	    result.eventsFound = events.length;
    96	    
    97	    const filtered = options?.filterFn 
    98	      ? events.filter(options.filterFn) 
    99	      : events;
   100	    
   101	    if (filtered.length < events.length) {
   102	      console.log(`[${name}] Filtered ${events.length - filtered.length} events`);
   103	    }
   104	    
   105	    result.eventsQueued = await queueEvents(filtered, name);
   106	    
   107	    if (result.eventsQueued === 0 && result.eventsFound > 0) {
   108	      result.status = 'partial';
   109	    }
   110	  } catch (err: any) {
   111	    result.errors.push(err.message || String(err));
   112	    result.status = 'fail';
   113	    console.error(`[${name}] Error:`, err);
   114	  }
   115	
   116	  return result;
   117	}
